// Üretilen dosya: tool/ozgun/uret.py. Yabancı Dil · Dünya alfabeleri, yazı sistemleri tarihi, etimoloji ve çeviri bilimi (Fenike, Kiril, Göktürk, Uygur, Hangıl, hiyeroglif, yalancı eşdeğerler, ödünçleme) (kolay).
const ozLanguage18Kolay = <(String, String, List<String>, String)>[
  ('Nesneleri doğrudan onların basitleştirilmiş resimleriyle gösteren en eski yazı türüne ne ad verilir?', 'Piktogram', ['Abugida sistemi', 'Fonemik alfabe', 'Ünsüz ebcedi'], 'Piktogramlar (resim yazıları), somut nesneleri görsel benzerlik yoluyla temsil eden ilk grafik işaretlerdir.'),
  ('Somut bir nesneyi değil, soyut bir kavramı ya da düşünceyi simgeleyen yazı birimi aşağıdakilerden hangisidir?', 'İdeogram', ['Hece işareti', 'Sesbirim harfi', 'Ayırıcı nokta'], 'İdeogramlar (kavram yazıları), doğrudan çizilemeyen soyut fikirleri sembolize eden işaretlerdir.'),
  ('Tarihte bilinen en eski tam gelişmiş yazı sistemi olan çivi yazısını hangi uygarlık icat etmiştir?', 'Sümerler', ['Fenikeliler', 'İbraniler', 'Romalılar'], 'Sümerler MÖ 4. binyılın sonlarında Mezopotamya\'da kil tabletler üzerine çivi yazısını geliştirmiştir.'),
  ('Her bir sembolün tek bir ünsüz veya ünlü sesi değil, bütünüyle bir heceyi karşıladığı yazı sistemine ne ad verilir?', 'Hece yazısı', ['Ebced yazısı', 'Tam alfabe', 'Kavram yazısı'], 'Hece yazısında (sillabary) "ka, ki, ku" gibi her hece birbirinden bağımsız ayrı bir sembolle gösterilir.'),
  ('Hem ünlü hem de ünsüz seslerin birbirine eşit statüde bağımsız harflerle gösterildiği ilk yazı sistemi aşağıdakilerden hangisidir?', 'Yunan alfabesi', ['Fenike yazısı', 'Mısır hiyeroglifleri', 'Arami ebcedi'], 'Yunanlılar Fenike ünsüz yazısını uyarlarken kullanmadıkları ünsüz harfleri bağımsız ünlü harflere dönüştürerek ilk gerçek alfabeyi yaratmıştır.'),
  ('Akdeniz\'de deniz ticaretiyle uğraşarak 22 ünsüz harflik yazı sistemlerini farklı kıyılara yayan İlk Çağ topluluğu hangisidir?', 'Fenikeliler', ['Sümerler', 'Hititler', 'Asurlular'], 'Fenikeliler deniz ticareti ağları sayesinde 22 harflik ebced sistemlerini Yunanlılar ve Aramiler başta olmak üzere Akdeniz dünyasına taşımıştır.'),
  ('Klasik Yunan alfabesinin ilk ve son harfleri sırasıyla aşağıdakilerden hangisidir?', 'Alfa ve Omega', ['Alfa ve Zeta', 'Beta ve Sigma', 'Alfa ve Tau'], 'Klasik 24 harfli Yunan alfabesi Alfa (Α) ile başlar ve uzun \'o\' sesini gösteren Omega (Ω) ile sona erer.'),
  ('Slav dillerini yazıya geçirmek amacıyla 9. yüzyılda Aziz Kiril ve Metodius\'un çalışmalarına dayanarak geliştirilen alfabe hangisidir?', 'Kiril alfabesi', ['Gotik alfabe', 'Runik alfabe', 'Ermeni alfabesi'], 'Kiril alfabesi, Bizanslı misyoner kardeşler Kiril ve Metodius\'un öğrencileri tarafından Birinci Bulgar İmparatorluğu\'nda Yunan harfleri temel alınarak şekillendirilmiştir.'),
  ('Arap ve İbrani yazı sistemlerinin satır üzerindeki temel yazım yönü aşağıdakilerden hangisidir?', 'Sağdan sola doğru', ['Soldan sağa doğru', 'Yukarıdan aşağıya doğru', 'Merkezden dışa doğru'], 'Kuzeybatı Sami ebced geleneğinden gelen Arap ve İbrani yazıları sağdan sola doğru yazılır.'),
  ('Arap alfabesindeki çoğu harfin kelime başında, ortasında, sonunda ve tek başına olmak üzere kaç farklı yazılış biçimi (allografı) bulunur?', 'Dört farklı biçimi', ['İki farklı biçimi', 'Altı farklı biçimi', 'Yedi farklı biçimi'], 'Arap yazısı işlek (bitişik) bir sistem olduğundan harflerin çoğu konumuna göre başta, ortada, sonda ve bağımsız olmak üzere 4 biçim alır (kendinden sonrakine bitişmeyen 6 harf hariç).'),
  ('Standart Arap alfabesinde (Hemze hariç tutulduğunda veya Elif ile sayıldığında) geleneksel olarak kaç temel harf bulunur?', '28 harf', ['22 harf', '24 harf', '33 harf'], 'Standart Arap ebcedi 28 temel ünsüz harften oluşur; Farsça ve Osmanlı Türkçesi gibi dillere uyarlandığında (پ, چ, ژ, گ eklenerek) bu sayı artmıştır.'),
  ('Bir harfin ses değerini değiştirmek veya ince bir ses farkını belirtmek için harfin altına, üstüne ya da üzerine eklenen nokta, çengel, şapka gibi işaretlere genel olarak ne denir?', 'Diyakritik işaret', ['Logografik kök', 'Sillabik taban', 'Piktografik simge'], 'Türkçedeki Ç, Ğ, Ö, Ş, Ü harflerindeki nokta ve çengellerde olduğu gibi harfe eklenerek yeni ses değeri kazandıran işaretlere diyakritik denir.'),
  ('İki ayrı harfin yan yana gelerek tek bir konuşma sesini (fonemi) temsil etmesine (örneğin İngilizcede /ʃ/ sesi için kullanılan "sh" veya Almancadaki "ch") ne ad verilir?', 'Digraf', ['İdeogram', 'Piktogram', 'Abugida'], 'Yunanca "iki yazı/harf" anlamına gelen digraf, tek bir sesi göstermek için iki harfin kalıplaşmış birlikteliğidir.'),
  ('İslam hat sanatında dik ve köşeli hatlarıyla erken dönem mushaflarda ve mimari kuşak yazılarında kullanılan en eski yazı üslubuna ne ad verilir?', 'Kûfî', ['Ta\'lik', 'Rik\'a', 'Divânî'], 'Adını Irak\'taki Kûfe şehrinden alan Kûfî hat, geometrik ve köşeli karakteriyle İslam\'ın ilk yüzyıllarında mushaf ve taş kitabelerde egemen olmuştur.'),
  ('Türkçenin 1928 Harf İnkılabı ile benimsediği yeni Türk alfabesinin ses-harf ilişkisi bakımından temel niteliği nedir?', 'Her harfin tek ve belirli bir sesi karşıladığı yüksek düzeyde fonemik bir Latin alfabesi olması', ['Kelimelerin tarihsel köklerini korumak için okunmayan sessiz harfleri bolca barındırması', 'Ünlü seslerin yalnızca vurgu düştüğü hecelerde yazıldığı yarı-ebced bir sistem olması', 'Yabancı kelimeleri ayrı bir hece tablosuyla gösteren karma bir yazı sistemi olması'], '1928 Türk alfabesi, Türkçedeki 8 ünlü ve 21 ünsüz sesbirimi bire bir gösteren şeffaf/fonemik bir Latin uyarlamasıdır.'),
  ('Yunan alfabesindeki "Phi (Φ), Chi (Χ), Psi (Ψ)" harflerinden hangisi Klasik Latin alfabesine doğrudan harf olarak alınmamış, bunun yerine "PH, CH, PS" gibi ikili harflerle (digraflarla) karşılanmıştır?', 'Üçü de klasik Latincede tek harf yerine PH, CH ve PS digraflarıyla yazılmıştır', ['Yalnızca Phi harfi alınmamış, Chi ve Psi doğrudan sona eklenmiştir', 'Yalnızca Psi harfi alınmamış, diğer ikisi C ve G harflerine dönüşmüştür', 'Üçü de Latin alfabesinin en başına konularak sesli harf yapılmıştır'], 'Romalılar Yunancadan ödünç aldıkları felsefe ve bilim terimlerindeki soluklu ünsüzleri (φ, χ) ve ψ sesini tek harf yerine PH (philosophia), CH (chorus) ve PS (psalmus) digraflarıyla aktarmıştır.'),
  ('Güney Asya ve Güneydoğu Asya\'daki (Hint, Bengal, Tamil, Tibet, Tay, Kmer vb.) onlarca abugida yazı sisteminin ortak tarihsel atası olan antik Hint yazısı hangisidir?', 'Brahmi yazısı', ['Kharosthi yazısı', 'Katakana yazısı', 'Glagol yazısı'], 'MÖ 3. yüzyılda İmparator Aşoka\'nın fermanlarında görülen Brahmi yazısı, Devanagari\'den Tay ve Tibet yazılarına kadar tüm Hint-Güneydoğu Asya abugida ailesinin ana köküdür.'),
  ('Sanskritçe, Hintçe, Marathice ve Nepalce gibi dillerin yazımında kullanılan, harflerin üst kısmından geçen kesintisiz yatay çizgiyle tanınan yazı sistemi hangisidir?', 'Devanagari', ['Nastaliq', 'Hiragana', 'Mhedruli'], '"Tanrısal şehir yazısı" anlamına gelen Devanagari, Hindistan\'ın en yaygın abugidası olup üstteki çamaşır ipi benzeri yatay çizgisiyle (şirorekha) kolayca ayırt edilir.'),
  ('Kesintisiz olarak en uzun süredir kullanımda olan Doğu Asya yazı sistemi aşağıdakilerden hangisidir?', 'Çin karakterleri', ['Hangıl alfabesi', 'Katakana hece yazısı', 'Kiril alfabesi'], 'MÖ 2. binyılın ikinci yarısından (Şang Hanedanı) beri kesintisiz evrilerek yaşayan Çin yazısı (Hanzi), kesintisiz kullanımı süren en eski yazı sistemidir.'),
  ('Çin yazısının arkeolojik olarak kanıtlanmış en eski olgun örnekleri olan Şang Hanedanı yazıtları hangi malzemeler üzerine kazınmıştır?', 'Öküz kürek kemikleri ve kaplumbağa kabukları üzerine', ['Papirüs yaprakları ve parşömen ruloları üzerine', 'Pişirilmiş kırmızı kil çivi tabletleri üzerine', 'İpek kumaşlar ve pamuklu kağıt yapraklar üzerine'], '"Fal kemikleri yazısı" (Jiaguwen) olarak bilinen en eski Çin karakterleri, kehanet amacıyla ateşe tutulan hayvan kemikleri ve kaplumbağa alt kabukları üzerine kazınmıştır.'),
  ('Çin karakterlerinin Latin alfabesiyle seslendirilmesini ve yabancılarla çocuklara öğretilmesini sağlayan uluslararası resmi romanizasyon (Latinleştirme) sistemi hangisidir?', 'Hanyu Pinyin', ['Hepburn sistemi', 'McCune-Reischauer sistemi', 'Wade-Giles sistemi'], 'Dilbilimci Zhou Youguang liderliğinde geliştirilip 1958\'de kabul edilen Hanyu Pinyin, Mandarin Çincesinin ses ve dört tonunu Latin harfleri ve ton işaretleriyle gösteren resmi sistemdir.'),
  ('Modern Japon yazı sistemi, bir cümle içinde eşzamanlı olarak bir arada kullanılan hangi üç temel yazı bileşeninden oluşur?', 'Kanji, Hiragana ve Katakana', ['Hanzi, Hangıl ve Pinyin', 'Devanagari, Brahmi ve Kharosthi', 'Kûfî, Nesih ve Rik\'a'], 'Japonca metinler Çince kökenli logogramlar (Kanji) ile iki yerli hece yazısının (Hiragana ve Katakana) aynı cümlede işbirliği yapmasıyla yazılır (bazen Latin Romaji de eklenir).'),
  ('Japoncada Çin\'den ödünç alınan ve isim, fiil, sıfat kökleri gibi temel anlamlı kelimeleri yazmak için kullanılan logografik karakterlere ne ad verilir?', 'Kanji', ['Hiragana', 'Katakana', 'Romaji'], '"Han (Çin) karakterleri" anlamına gelen Kanji, Japoncadaki sözcük köklerini ve somut/soyut kavramları temsil eden logogramlardır.'),
  ('Kore dilinin yazımında kullanılan "Hangıl" alfabesi 15. yüzyılda Joseon Hanedanı\'nın hangi hükümdarı öncülüğünde icat edilmiştir?', 'Büyük Kral Sejong', ['İmparator Gwanggaeto', 'Kral Taejo', 'İmparator Gojong'], 'Kral Sejong, klasik Çince (Hanja) öğrenemeyen sıradan halkın kendi dilini kolayca okuyup yazabilmesi için 1443\'te Hangıl\'ı tamamlamış ve 1446\'da ilan etmiştir.'),
  ('Hangıl, yapısal olarak sesbirimleri (ünlü ve ünsüzleri) gösteren bir alfabe olmasına rağmen sayfa üzerinde doğrusal dizilmek yerine nasıl yazılır?', 'Harflerin hece sınırlarına göre kare benzeri morfo-sillabik bloklar halinde gruplanmasıyla', ['Harflerin kelime sonuna kadar alttan kesintisiz bir el yazısı çizgisiyle birleştirilmesiyle', 'Sadece ünsüzlerin büyük boy yazılıp ünlülerin sayfanın en alt dipnotuna toplanmasıyla', 'Her cümlenin ortadan başlayıp saat yönünde sarmal halkalar oluşturarak büyümesiyle'], 'Örneğin "한글" (Han-gıl) kelimesinde ㅎ+ㅏ+ㄴ ve ㄱ+ㅡ+ㄹ harfleri yan yana "ㅎㅏㄴㄱㅡㄹ" diye dizilmez; her hece görünüm olarak Kanji karesini andıran derli toplu bir blok oluşturur.'),
  ('Modern Doğu Asya yayıncılığında Çince, Japonca ve geleneksel Korece metinlerin iki farklı standart sayfa yerleşim yönü hangileridir?', 'Soldan sağa yatay satırlar veya yukarıdan aşağıya inip sağdan sola ilerleyen dikey sütunlar', ['Sağdan sola yatay satırlar veya aşağıdan yukarıya çıkıp soldan sağa ilerleyen sütunlar', 'Yalnızca boustrophedon (öküz dönüşü) düzeninde zikzaklı yatay satırlar', 'Sadece sayfanın tam ortasından kenarlara doğru genişleyen çapraz satırlar'], 'Geleneksel Doğu Asya yazısı (tategaki) yukarıdan aşağıya yazılır ve sütunlar sağdan sola dizilir (bu yüzden geleneksel kitaplar ve mangalar "sağdan" açılır); modern bilimsel/yatay dizgide (yokogaki) ise soldan sağa yazılır.'),
  ('Görme engellilerin parmak uçlarıyla dokunarak okuyup yazabilmesi için 1824 yılında Fransız eğitimci Louis Braille tarafından geliştirilen kabartma yazı sistemi kaç noktalı hücre esasına dayanır?', 'Altı noktalı dikdörtgen hücre', ['On iki noktalı dairesel hücre', 'Dört çizgili kare hücre', 'Sekiz köşeli yıldız hücre'], 'Louis Braille, Napolyon ordusu için tasarlanan 12 noktalı "gece yazısını" parmak ucunun tek dokunuşta algılayabileceği 2×3 = 6 noktalı hücreye indirgeyerek küresel kabartma yazı devrimini gerçekleştirmiştir.'),
  ('Bilgisayarlarda ve dijital iletişimde Latin, Kiril, Arap, Devanagari, Çince, Hangıl ve antik hiyeroglifler dahil dünyadaki tüm yazı sistemlerinin karakterlerine benzersiz birer sayısal kod atayan evrensel standart hangisidir?', 'Unicode', ['Boustrophedon', 'Karolenj', 'Reklama'], 'Unicode konsorsiyumu, farklı yazı sistemlerinin aynı belgede ve ekranda bozulmadan görüntülenmesini sağlayan evrensel karakter kodlama standardıdır.'),
  ('Aşağıdaki dillerden hangisi tarih boyunca ve standart kullanımda "Kiril alfabesi" yerine "Latin alfabesi" kullanan Slav dillerinden biridir?', 'Lehçe', ['Rusça', 'Bulgarca', 'Sırpçanın geleneksel kilise kolu dışında Bulgarca ve Makedonca'], 'Tarihsel olarak Ortodoks Hristiyanlığı benimseyen Slav halkları (Ruslar, Bulgarlar, Ukraynalılar, Sırplar) Kiril alfabesini kullanırken; Katolik kilisesine bağlanan Batı ve Güney Slavları (Polonyalılar, Çekler, Slovaklar, Hırvatlar, Slovenler) Latin alfabesini benimsemiştir.'),
  ('Aşağıdaki ülkelerden hangisinde resmi yazı sistemi olarak Latin, Kiril veya Arap alfabesi değil, tamamen kendine özgü ulusal bir alfabe kullanılmaktadır?', 'Gürcistan ve Ermenistan', ['Türkiye ve Azerbaycan', 'İspanya ve Portekiz', 'Mısır ve Ürdün'], 'Kafkasya\'daki Gürcistan (Gürcü Mhedruli alfabesi) ve Ermenistan (Ermeni alfabesi), MS 5. yüzyıldan bu yana komşularından bağımsız kendi ulusal tam alfabelerini kullanmaktadır.'),
  ('Bir alfabede "A - a, B - b, G - g" örneğinde olduğu gibi hem büyük harf (majüskül) hem de küçük harf (minüskül) dizisinin bulunmasına tipografide "bikameral" (iki kasalı) yapı denir; buna göre aşağıdaki yazı sistemlerinden hangileri bikameraldir?', 'Latin, Yunan, Kiril ve Ermeni alfabeleri', ['Arap, İbrani, Devanagari ve Hangıl yazıları', 'Çin Hanzi, Japon Hiragana, Katakana ve Tay yazıları', 'Fenike, Göktürk, Tibet ve Gürcü Mhedruli yazıları'], 'Dünya yazılarının büyük çoğunluğu (Arap, İbrani, Devanagari, Çince, Japonca, Korece, Gürcüce) büyük-küçük harf ayrımı olmayan "unikameral" sistemlerdir; büyük-küçük harf ikiliği yalnızca Latin, Yunan, Kiril, Ermeni (ve tarihsel Kıpti/Adlam vb. birkaç sistem) ile sınırlıdır.'),
  ('Orhun Yazıtları\'nda kullanılan Göktürk (Orhun) alfabesini 1893 yılında çözerek bilim dünyasına tanıtan Danimarkalı dilbilimci kimdir?', 'Vilhelm Thomsen', ['Vasily Radloff', 'Gyula Nemeth', 'Gerard Clauson'], 'Danimarkalı dilbilimci Vilhelm Thomsen, 1893 yılında Orhun alfabesini çözmeyi başarmıştır.'),
  ('Klasik Orhun (Göktürk) alfabesinde toplam kaç adet harf (damga) bulunmaktadır?', '38', ['29', '18', '44'], 'Klasik Orhun alfabesi 4\'ü ünlü, 34\'ü ünsüz ve bileşik ses olmak üzere toplam 38 damgadan oluşur.'),
  ('Göktürk alfabesindeki 4 ünlü damgadan her biri kaç farklı ünlü sesi karşılayacak biçimde kullanılmıştır?', 'İkişer ünlü sesi', ['Üçer ünlü sesi', 'Dörder ünlü sesi', 'Yalnızca tek bir ünlü sesi'], 'Göktürk alfabesindeki 4 ünlü işareti sırasıyla a/e, ı/i, o/u ve ö/ü olmak üzere ikişer ünlüyü karşılar.'),
  ('Orhun Yazıtları\'nda satır içi yazım yönü genel kural olarak nasıldır?', 'Sağdan sola doğru', ['Soldan sağa doğru', 'Aşağıdan yukarıya doğru', 'Çapraz sarmal düzende'], 'Orhun alfabesinde metinler satır düzeninde genel olarak sağdan sola doğru yazılmıştır.'),
  ('Türklerin Göktürk alfabesinden sonra yerleşik kültür ve kağıt kullanımıyla birlikte yaygın biçimde benimsedikleri ikinci büyük milli alfabe hangisidir?', 'Uygur alfabesi', ['Kiril alfabesi', 'Latin alfabesi', 'Ermeni alfabesi'], 'Göktürk alfabesinin ardından Türkler arasında geniş coğrafyada uzun süre kullanılan alfabe Uygur alfabesidir.'),
  ('Klasik Uygur alfabesinde harf sayısı yaklaşık olarak kaçtır?', '18', ['38', '29', '33'], 'Uygur alfabesi, 3 veya 4\'ü ünlü görevinde kullanılan toplam 14 ila 18 harfli dar kapsamlı bir alfabedir.'),
  ('Türklerin İslamiyet\'i kitleler halinde kabul ettiği hangi devlet döneminde Arap alfabesi Türk yazı dili için resmi ve yaygın alfabe haline gelmiştir?', 'Karahanlılar döneminde', ['Göktürkler döneminde', 'Avrupa Hunları döneminde', 'Hazar Kağanlığı döneminde'], '10. yüzyılda Satuk Buğra Han zamanında İslamiyet\'i benimseyen Karahanlılar döneminde Arap alfabesi yaygınlaşmıştır.'),
  ('Türkiye Cumhuriyeti\'nde 1353 sayılı "Türk Harflerinin Kabul ve Tatbiki Hakkında Kanun" hangi tarihte Türkiye Büyük Millet Meclisi tarafından kabul edilmiştir?', '1 Kasım 1928', ['29 Ekim 1923', '3 Mart 1924', '12 Temmuz 1932'], 'Yeni Türk harflerine geçişi sağlayan 1353 sayılı kanun 1 Kasım 1928 tarihinde kabul edilmiştir.'),
  ('1928 yılında kabul edilen Yeni Türk Alfabesi\'nde kaçı ünlü, kaçı ünsüz olmak üzere toplam 29 harf yer almıştır?', '8 ünlü ve 21 ünsüz harf', ['9 ünlü ve 20 ünsüz harf', '7 ünlü ve 22 ünsüz harf', '10 ünlü ve 19 ünsüz harf'], 'Yeni Türk Alfabesi a, e, ı, i, o, ö, u, ü olmak üzere 8 ünlü ve 21 ünsüzle toplam 29 harften oluşur.'),
  ('Harf İnkılabı\'nın ardından okuma-yazma seferberliğini ülke çapında yaygınlaştırmak amacıyla 1928 sonlarında açılan yaygın eğitim kurumlarına ne ad verilmiştir?', 'Millet Mektepleri', ['Köy Enstitüleri', 'Halkodaları', 'Darülfünun Şubeleri'], 'Yeni harfleri her yaştan vatandaşa öğretmek için açılan kurumlar Millet Mektepleri olmuş ve Atatürk "Başöğretmen" unvanını almıştır.'),
  ('Moldova sınırları içinde yaşayan Hristiyan Oğuz Türkleri olan Gagavuzlar, Sovyet dönemindeki Kiril alfabesi kullanımının ardından hangi esaslı alfabeye geçmişlerdir?', 'Latin esaslı alfabeye', ['Yunan esaslı alfabeye', 'Arap esaslı alfabeye', 'İbrani esaslı alfabeye'], 'Gagavuz Türkleri 1990\'lı yıllarda Türkiye Türkçesi alfabesine çok yakın 31 harfli Latin esaslı alfabeye geçmişlerdir.'),
  ('Dildeki sözcüklerin hangi kökten türediğini, tarihsel süreçte geçirdiği ses ve anlam değişmelerini bilimsel yöntemlerle inceleyen dilbilim dalına ne ad verilir?', 'Etimoloji (Köken bilimi)', ['Morfoloji (Biçim bilimi)', 'Sentaks (Söz dizimi)', 'Ortoepi (Doğru söyleyiş bilimi)'], 'Sözcüklerin kökenini ve tarihsel evrimini araştıran bilim dalı etimolojidir (köken bilimi).'),
  ('Türk dilinin bilinen ilk ansiklopedik sözlüğü olan ve 11. yüzyılda Türkçe kelimelerin kökeni, yapısı ve boylara göre ses farkları hakkında eşsiz bilgiler sunan eser hangisidir?', 'Divanü Lügati\'t-Türk', ['Kutadgu Bilig', 'Atabetü\'l-Hakayık', 'Muhakemetü\'l-Lügateyn'], 'Kaşgarlı Mahmud\'un 1072-1074 yıllarında yazdığı Divanü Lügati\'t-Türk, Türk etimolojisi ve diyalektolojisinin temel kaynağıdır.'),
  ('Bir sözcüğün eskiden karşıladığı genel ve geniş kavram alanından çıkarak zamanla o kavramın yalnızca bir alt türünü veya parçasını karşılar hale gelmesine ne ad verilir?', 'Anlam daralması', ['Anlam genişlemesi', 'Anlam iyileşmesi', 'Halk etimolojisi'], 'Genel bir anlam taşıyan kelimenin zamanla daha özel ve sınırlı bir anlamda kullanılmasına anlam daralması denir.'),
  ('Başlangıçta yalnızca özel bir nesneyi, tek bir türü ya da sınırlı bir durumu karşılayan sözcüğün zamanla bütün bir türü veya daha geniş bir kavram alanını anlatır hale gelmesine ne ad verilir?', 'Anlam genişlemesi', ['Anlam daralması', 'Anlam kötüleşmesi', 'Halk etimolojisi'], 'Dar kapsamlı bir kelimenin zamanla daha genel ve kapsayıcı bir anlam kazanmasına anlam genişlemesi denir.'),
  ('Eskiden olumsuz, kaba veya aşağılayıcı bir anlam taşıyan bir sözcüğün zaman içinde olumlu, saygın veya beğenilen bir anlam kazanmasına ne ad verilir?', 'Anlam iyileşmesi (anlam yükselmesi)', ['Anlam kötüleşmesi (anlam bayağılaşması)', 'Anlam daralması', 'Halk etimolojisi'], 'Sözcüğün tarihsel süreçte olumsuz anlamdan olumlu ve saygın bir anlama geçmesine anlam iyileşmesi (meliorasyon) denir.'),
  ('Başlangıçta olumlu, saygın veya tarafsız bir anlam taşıyan bir sözcüğün zaman içinde olumsuz, küçümseyici ya da kaba bir anlam kazanmasına ne ad verilir?', 'Anlam kötüleşmesi (anlam bayağılaşması)', ['Anlam iyileşmesi (anlam yükselmesi)', 'Anlam genişlemesi', 'Ödünç çeviri (kalk)'], 'Sözcüğün olumlu ya da nötr bir anlamdan olumsuz ve aşağılayıcı bir anlama kaymasına anlam kötüleşmesi (pejorasyon) denir.'),
  ('Konuşurların yabancı kökenli veya artık kökü unutulmuş yerli bir sözcüğü, ses ve anlam çağrışımı yoluyla kendi dillerinde bildikleri tanıdık kelimelere benzeterek değiştirmelerine ne ad verilir?', 'Halk etimolojisi (yakıştırmaca)', ['Bilimsel kök türetimi', 'Büyük ünlü uyumu', 'Ulama (liaison)'], 'Yabancı veya körelmiş sözcüklerin tanıdık kelimelerle ilişkilendirilerek sesçe değiştirilmesine halk etimolojisi (yakıştırma) denir.'),
  ('Fransızca "eau de Cologne" (Köln suyu) tamlamasının Türkçeye "kolonya" olarak geçtikten sonra Anadolu ağızlarında tanıdık "kol" veya "koymak" kelimeleriyle değil, İngilizce "sleeping-car" (yataklı vagon) sözcüğünden Fransızca aracılığıyla geçen ya da Fransızca "garde-frein" (fren görevlisi) kelimesinin halk ağzında "gardıfren" yerine "kardelen" değil; Farsça "âyîne-dâr" veya Arapça "sa\'ter" değil, Yunanca "kefalopodi / ahtapot" yerine "sekizayak" değil, İtalyanca "cavo / gomina" değil; Arapça "mevsim" yerine, Yunanca "angouria" (salatalık) ve "aggouraki" değil, Farsça "bâdincân" kelimesinin halk ağzında tanıdık "can" ve "patlamak" çağrışımıyla hangi sebze adına dönüşmesi ses ve halk etimolojisi etkileşimidir?', 'Patlıcan', ['Domates', 'Ispanak', 'Pırasa'], 'Farsça "bâdincân / bâdengân" sözcüğü Türkçede ses değişimi ve tanıdık hece kalıplarına yaklaştırmayla "patlıcan" biçimini almıştır.'),
  ('Bir dilin başka bir dilden kültürel, ticari, coğrafi veya tarihsel ilişkiler sonucunda sözcük ya da terim almasına dilbilimde ne ad verilir?', 'Sözlüksel ödünçleme', ['Biçimbirimsel çekimleme', 'Ünsüz yumuşaması', 'Art zamanlı türetme'], 'Dillerin birbirinden sözcük alışverişinde bulunmasına ödünçleme (borrowing / loanword), alınan kelimelere de alıntı sözcük denir.'),
  ('Türkçede denizcilik, balıkçılık ve rüzgar adlarıyla ilgili söz varlığında ("liman, körfez, fener, poyraz, lodos, levrek, lüfer, kefal") ağırlıklı olarak hangi dillerden yapılmış ödünçlemeler görülür?', 'Yunanca ve İtalyanca', ['Çince ve Moğolca', 'Rusça ve Lehçe', 'Soğdca ve Toharca'], 'Anadolu ve Akdeniz coğrafyasındaki denizcilik ve balıkçılık terimlerinin büyük bölümü Yunanca (Rumca) ve İtalyanca (Venedik/Ceneviz) kökenlidir.'),
  ('Türkçedeki "namaz, oruç, abdest, peygamber, günah, sevap" gibi temel İslami ibadet ve inanç sözcükleri köken bakımından hangi dilden ödünçlenmiştir?', 'Farsçadan', ['Arapçadan', 'Yunancadan', 'Moğolcadan'], 'Türkler İslamiyet\'i İran (Maveraünnehir-Horasan) kültür havzası üzerinden tanıdıkları için namaz, oruç (< rûze), abdest ve peygamber gibi terimleri Farsçadan almışlardır.'),
  ('Türkçeden batı ve dünya dillerine geçerek neredeyse bütün dillerde benzer seslerle kullanılan en ünlü süt ürünü adı hangisidir?', 'Yoğurt', ['Tereyağı', 'Dondurma', 'Kaymak'], 'Türkçe "yoğurmak / yoğun" köküyle ilişkili olan "yoğurt" sözcüğü İngilizce (yogurt/yoghurt), Fransızca, Almanca ve İspanyolca dahil tüm dünya dillerine Türkçeden geçmiştir.'),
  ('Türkiye Türkçesindeki "kahvaltı" sözcüğü hangi iki kelimenin tarihsel süreçte birleşip ses düşmesine uğramasıyla oluşmuştur?', 'Kahve ve altı', ['Kahır ve altı', 'Kadeh ve vakti', 'Kavurma ve aş'], '"Kahve içmeden önce yenilen hafif yiyecek / kahve altı" anlamındaki "kahve altı" tamlaması, ünlü düşmesiyle "kahvaltı" biçiminde kalıplaşmıştır.'),
  ('Bir dildeki en temel sayı adlarının ("bir, iki, üç, beş, on"), organ adlarının ("baş, göz, kulak, el, ayak"), zamirlerin ("ben, sen, o, biz") ve temel eylemlerin ("al-, ver-, gel-, git-, yat-, uyu-") başka dillerden pek ödünçlenmeyen bütününe ne ad verilir?', 'Çekirdek (temel) söz varlığı', ['Geçici moda terimler', 'Argo ve jargon katmanı', 'Teknik ödünçlemeler'], 'Dillerin akrabalığını ve öz yapısını belirleyen, dış etkilere en dirençli sözcük grubuna temel (çekirdek) söz varlığı denir.'),
  ('Göktürk damgalarından Uygur, Arap ve Kiril yazılarına, oradan 1928 Yeni Türk Alfabesi\'ne uzanan alfabe tarihi ile Türkçenin etimolojik gelişimi birlikte değerlendirildiğinde ulaşılabilecek en doğru genel yargı hangisidir?', 'Türkler tarih boyunca farklı coğrafya, din ve medeniyet çevreleriyle temas ederek çeşitli alfabeler kullanmış ve sözcük alışverişinde bulunmuş, ancak dilin sondan eklemeli yapısını ve çekirdek söz varlığını korumuştur', ['Alfabe değiştiren her toplum gibi Türkler de her alfabe değişikliğinde eski dilbilgisi kurallarını ve bütün fiil köklerini tamamen terk ederek yeni bir dil kurmuştur', 'Türkçenin ses yapısını en kusursuz biçimde gösteren alfabe yalnızca sessiz harflerden oluşan Soğd ve Uygur alfabeleri olmuştur', 'Diller arası ödünçlemeler yalnızca tek yönlü gerçekleşmiş, Türkçe komşu dillere hiçbir dönem sözcük vermemiştir'], 'Türk dili, Göktürkçeden bugüne farklı yazı sistemleri ve kültürel temaslar içinden geçmesine rağmen ses kurallarını, eklemeli biçimbilimini ve temel söz varlığını sürdürmüştür.'),
  ('Çeviri sürecinde bir metnin ilk olarak kaleme alındığı özgün dile çeviribilimde ne ad verilir?', 'Kaynak dil', ['Erek dil', 'Ara dil', 'Yapay yardımcı dil'], 'Çevirisi yapılan özgün metnin diline kaynak dil, metnin aktarıldığı dile ise erek dil denir.'),
  ('Bir metnin veya konuşmanın çeviri yoluyla aktarıldığı hedef dile çeviribilim terminolojisinde hangi ad verilir?', 'Erek dil', ['Kaynak dil', 'Ölü dil', 'Ana dil'], 'Çeviri eyleminin yöneldiği ve yeni metnin üretildiği dil erek (hedef) dil olarak adlandırılır.'),
  ('Konuşmacı konuşmasını sürdürürken çevirmenin ses yalıtımlı kabinde kulaklık ve mikrofon yardımıyla anında yaptığı çeviri türü hangisidir?', 'Eşzamanlı (simultane) çeviri', ['Ardıl (konsekütif) çeviri', 'Yazılı metin çevirisi', 'Noter onaylı yeminli çeviri'], 'Konuşmacıyla neredeyse aynı anda kabin içinde gerçekleştirilen sözlü çeviriye eşzamanlı (simultane) çeviri denir.'),
  ('Konuşmacının birkaç cümle veya bölüm konuşup duraklamasının ardından çevirmenin aldığı notlara dayanarak yaptığı sözlü çeviri hangisidir?', 'Ardıl (konsekütif) çeviri', ['Eşzamanlı (simultane) çeviri', 'Altyazı (subtitling) çevirisi', 'Fısıltı (chuchotage) çevirisi'], 'Konuşmacının sözünü tamamlamasını veya duraklamasını bekleyerek ardından yapılan çeviri türü ardıl (konsekütif) çeviridir.'),
  ('İki dilde yazılış veya okunuş bakımından birbirine çok benzeyen ancak anlamları tamamen ya da kısmen farklı olan sözcüklere ne ad verilir?', 'Yalancı eşdeğerler (false friends)', ['Eş anlamlılar (synonyms)', 'Eş sesliler (homophones)', 'Deyimsel fiiller (phrasal verbs)'], 'Biçimsel benzerlik nedeniyle çevirmeni yanıltabilen farklı anlamlı sözcük çiftlerine yalancı eşdeğerler denir.'),
  ('İngilizce "library" sözcüğünün Türkçedeki doğru karşılığı aşağıdakilerden hangisidir?', 'Kütüphane', ['Kitap satış mağazası', 'Kırtasiye dükkanı', 'Basımevi ve matbaa'], '"Library" ödünç kitap alınan kütüphane demektir; kitapçı anlamına gelen sözcük "bookshop" veya "bookstore"dur.'),
  ('İngilizce "fabric" sözcüğü Türkçeye çevrildiğinde hangi anlama gelir?', 'Kumaş / dokuma', ['Sanayi fabrikası', 'Üretim atölyesi', 'Montaj tesisi'], '"Fabric" kumaş veya dokuma demektir; Türkçe "fabrika" sözcüğünün İngilizce karşılığı "factory" veya "plant"tir.'),
  ('İngilizce "actual" sıfatının Türkçedeki gerçek anlamı aşağıdakilerden hangisidir?', 'Gerçek / asıl', ['Güncel / aktüel', 'Geçici / anlık', 'Gelecekteki / olası'], '"Actual" gerçek, asıl, fiili anlamına gelir; Türkçedeki "aktüel/güncel" anlamı İngilizcede "current" veya "topical" ile karşılanır.'),
  ('İngilizce "sympathetic" sıfatı bir kişinin hangi özelliğini tanımlamak için kullanılır?', 'Halden anlayan / şefkatli', ['Sevimli / cana yakın', 'Eğlenceli / neşeli', 'Yakışıklı / gösterişli'], 'İngilizcede "sympathetic" başkasının acısını paylaşan, anlayışlı demektir; Türkçedeki "sempatik" için "likeable" veya "pleasant" kullanılır.'),
  ('İngilizce "sensible" sözcüğünün Türkçedeki doğru karşılığı nedir?', 'Mantıklı / sağduyulu', ['Aşırı duygusal / alıngan', 'Kırılgan / narin', 'Sanata düşkün / estetik'], '"Sensible" aklı başında, mantıklı demektir; "hassas, alıngan, duyarlı" anlamını ise "sensitive" sözcüğü taşır.'),
  ('Bir yazılımın, video oyununun veya web sitesinin sadece dilini çevirmekle kalmayıp hedef ülkenin para birimi, tarih formatı ve kültürel normlarına uyarlanması işlemine ne denir?', 'Yerelleştirme', ['Birebir sözcük çevirisi', 'Fonetik transkripsiyon', 'Özetleme çevirisi'], 'Yerelleştirme (L10n), ürünün hedef pazarın dilsel, teknik ve kültürel beklentilerine tam uyumlu hale getirilmesidir.'),
  ('Başka bir dildeki birleşik sözcük veya deyimin bileşenlerinin hedef dile sözcüğü sözcüğüne çevrilerek aktarılmasına (örneğin İngilizce "skyscraper" -> Türkçe "gökdelen") ne ad verilir?', 'Öyküntü (calque)', ['Ses aktarımı (transkripsiyon)', 'Sözlü özetleme', 'Yalancı eşdeğerlik'], 'Kaynak dildeki yapının parçalarının birebir tercüme edilerek hedef dilde yeni bir kavram türetilmesine öyküntü (calque) denir.'),
  ('İngilizce "chef" sözcüğü Türkçede hangi meslek grubunu ifade eder?', 'Profesyonel başaşçı', ['Fabrika vardiya amiri', 'Orkestra yöneticisi', 'Tren istasyonu müdürü'], 'İngilizcede "chef" mutfak şefi/başaşçı anlamındadır; büro veya kurum yöneticisi anlamındaki "şef" için "boss", "head" veya "supervisor" kullanılır.'),
  ('İngilizce "novel" isim olarak kullanıldığında aşağıdakilerden hangisini karşılar?', 'Roman', ['Kısa magazin haberi', 'Yeni yıl takvimi', 'Resimli duvar afişi'], 'Sıfat olarak "yeni/özgün" anlamına gelen "novel", isim olarak edebi bir tür olan "roman" demektir.'),
  ('İngilizce "receipt" sözcüğünün alışveriş bağlamındaki Türkçe karşılığı nedir?', 'Ödeme fişi / makbuz', ['Yemek tarifi listesi', 'Doktor ilaç reçetesi', 'Kullanım kılavuzu'], '"Receipt" kasa fişi veya makbuz demektir; yemek tarifi için "recipe", doktor reçetesi için "prescription" kullanılır.'),
  ('İngilizce "magazine" sözcüğü yayın dünyasında aşağıdakilerden hangisini ifade eder?', 'Süreli dergi', ['Alışveriş mağazası', 'Büyük süpermarket', 'Giyim butiği'], '"Magazine" haftalık veya aylık dergi (ve silah şarjörü) demektir; Türkçedeki "mağaza" İngilizcede "store" veya "shop"tur.'),
  ('İngilizce "billion" sayı sözcüğü Türkçede hangi sayısal değere karşılık gelir?', 'Milyar (10 üzeri 9)', ['Trilyon (10 üzeri 12)', 'Milyon (10 üzeri 6)', 'Katrilyon (10 üzeri 15)'], 'Modern İngilizcede kısa ölçek kullanılır ve "one billion" bin milyona yani Türkçedeki "bir milyar"a eşittir.'),
  ('İngilizce "ambulance" gibi yazılışı da anlamı da Türkçedeki "ambulans" ile örtüşen sözcüklere çeviribilimde ne ad verilir?', 'Gerçek eşdeğerler (true friends)', ['Yalancı eşdeğerler (false friends)', 'Zıt anlamlılar (antonyms)', 'Deyimsel öyküntüler (idiomatic calques)'], 'Biçim ve anlam bakımından iki dilde de aynı kavramı karşılayan sözcüklere gerçek eşdeğerler (true cognates/friends) denir.'),
  ('İngilizce "gymnasium" (veya kısaca "gym") sözcüğü modern İngilizcede nereyi ifade eder?', 'Spor salonu', ['Akademik lise binası', 'Üniversite amfisi', 'Halk kütüphanesi'], 'Almancada akademik liseyi karşılayan "Gymnasium", İngilizcede spor ve jimnastik salonu anlamına gelir.'),
  ('Yazılı bir kaynak metnin çevirmen tarafından okunurken aynı anda hedef dilde yüksek sesle sözlü olarak ifade edilmesine ne ad verilir?', 'Yazılı metinden sözlü çeviri', ['Kabinde eşzamanlı konferans çevirisi', 'Zaman kodlu altyazı çevirisi', 'Stüdyo içi dudak senkronlu dublaj'], 'Yazılı bir belgeyi bakarak anında hedef dilde seslendirme eylemine yazılıdan sözlüye çeviri (sight translation) denir.'),
  ('İngilizce "cartoon" sözcüğü günlük dilde aşağıdakilerden hangisini anlatır?', 'Çizgi film / karikatür', ['Oluklu mukavva kutu', 'Kalın dosya kağıdı', 'Sigara paketi kartonu'], '"Cartoon" çizgi film veya karikatür demektir; mukavva/karton kutu anlamı İngilizcede "cardboard" veya "carton" ile ifade edilir.'),
  ('İngilizce "brave" sıfatının Türkçedeki doğru karşılığı nedir?', 'Cesur / yürekli', ['Aferin / tebrikler', 'Uslu / itaatkar', 'Kibar / görgülü'], '"Brave" cesur demektir; takdir bildiren "bravo!" ünlemiyle veya Fransızcadaki "uslu/iyi" anlamıyla karıştırılmamalıdır.'),
  ('Sinema ve televizyon çevirilerinde kaynak dildeki konuşmaların silinerek yerine hedef dildeki seslendirmelerin yerleştirilmesi yöntemine ne denir?', 'Dublaj (seslendirme)', ['Altyazı (subtitling)', 'Üst yazı (surtitling)', 'Fısıltı çevirisi (chuchotage)'], 'Görsel-işitsel çeviride özgün konuşma kanalının hedef dildeki ses sanatçılarıyla değiştirilmesi dublajdır.'),
  ('İngilizce "camera" sözcüğü günlük kullanımda öncelikle hangi cihazı ifade eder?', 'Fotoğraf makinesi / görüntü kaydedici', ['Bahçe çardak kameriyesi', 'Yatak odası bölmesi', 'Parlamento meclis salonu'], 'Latince "oda" kökeninden gelse de modern İngilizcede "camera" fotoğraf makinesi veya video kamera demektir; bahçe çardağı "gazebo"dur.'),
];
